export type ParsedClaimInstruction<
  TProgram extends string = typeof VESTING_POSITIONS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    user: TAccountMetas[0];
    collection: TAccountMetas[1];
    updateAuthority: TAccountMetas[2];
    mint: TAccountMetas[3];
    campaignAta: TAccountMetas[4];
    userAta: TAccountMetas[5];
    campaign: TAccountMetas[6];
    /** existing mpl-core asset (any owner) on subsequent claims */
    asset: TAccountMetas[7];
    claimReceipt: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
    associatedTokenProgram: TAccountMetas[11];
    mplCoreProgram: TAccountMetas[12];
  };
  data: ClaimInstructionData;
};

export function parseClaimInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedClaimInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      collection: getNextAccount(),
      updateAuthority: getNextAccount(),
      mint: getNextAccount(),
      campaignAta: getNextAccount(),
      userAta: getNextAccount(),
      campaign: getNextAccount(),
      asset: getNextAccount(),
      claimReceipt: getNextAccount(),
      systemProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      mplCoreProgram: getNextAccount(),
    },
    data: getClaimInstructionDataDecoder().decode(instruction.data),
  };
}
